components.chart:
erDiagram
  ORDER ||--o{ RECEIPT_ATTEMPT : has
  CUSTOMER ||--o{ ORDER : places
  ORDER {
    int id PK
    int customer_id FK
    string status
  }
  RECEIPT_ATTEMPT {
    int id PK
    int order_id FK
    string outcome
    datetime tried_at
  }
  CUSTOMER {
    int id PK
    string email
  }

classDiagram
  class ApplicationJob {
    +perform_later(args)
    +retry_on(error)
  }
  class ReceiptJob {
    +perform(order_id)
  }
  class ReceiptMailer {
    +deliver(order)
  }
  ApplicationJob <|-- ReceiptJob
  ReceiptJob ..> ReceiptMailer : calls
